import React, { useEffect, useState } from 'react';

// Rows come from public/data/population_showcase.json, generated by scripts/build_population_showcase.py from the project's real
// ClinVar x gnomAD v4.1 cache. No frequency is typed into this file.
const fmtAf = (v) => (v === null || v === undefined ? 'n/a' : v === 0 ? '0' : v < 0.001 ? v.toExponential(2) : v.toFixed(4));

export default function ResearchSection() {
  const [data, setData] = useState(null);
  const [failed, setFailed] = useState(false);
  useEffect(() => {
    fetch('/data/population_showcase.json').then((r) => (r.ok ? r.json() : Promise.reject(new Error(String(r.status))))).then(setData).catch(() => setFailed(true));
  }, []);
  return (
    <section className="w-full py-space-3xl" id="research">
      <div className="max-w-container-max mx-auto px-gutter-mobile lg:px-gutter-desktop">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-space-2xl items-center">
          <div className="lg:col-span-6 flex flex-col">
            <span className="font-label-sm text-label-sm text-secondary font-semibold uppercase tracking-wider block mb-space-2xs">
              Demographic Genome Variation
            </span>
            <h2 className="font-headline-lg text-headline-lg text-primary tracking-tight mb-space-md">
              Population-aware rare-disease prioritization.
            </h2>
            <p className="font-body-lg text-body-lg text-on-surface-variant mb-space-md">
              Global genomic frequency data may not fully represent the rich genetic variation observed across Indian populations. The platform reports population-frequency evidence next to phenotype and retrieval evidence, and keeps it separate from the ranking score.
            </p>
            <p className="font-body-md text-body-md text-on-surface-variant mb-space-lg">
              Evidence currently comes from gnomAD v4.1 (global and South Asian), joined to ClinVar pathogenic variants at gene level. IndiGen data are not available, gnomAD South Asian is not an India-specific dataset, and the population weight is 0, so no re-weighting is applied and no benefit is claimed.
            </p>
            <div className="flex flex-col gap-space-sm">
              <div className="flex items-start gap-space-sm">
                <div className="w-8 h-8 rounded-full bg-surface-container flex items-center justify-center text-secondary shrink-0">
                  <span className="material-symbols-outlined text-[18px]">strikethrough_s</span>
                </div>
                <div>
                  <span className="block font-title-md text-title-md text-primary">Global and South Asian kept separate</span>
                  <span className="font-body-sm text-body-sm text-on-surface-variant">gnomAD global and gnomAD South Asian frequencies are shown side by side under their own names. IndiGen (Indian) data require access from CSIR-IGIB and are not integrated; nothing is substituted for them.</span>
                </div>
              </div>
              <div className="flex items-start gap-space-sm">
                <div className="w-8 h-8 rounded-full bg-surface-container flex items-center justify-center text-secondary shrink-0">
                  <span className="material-symbols-outlined text-[18px]">calculate</span>
                </div>
                <div>
                  <span className="block font-title-md text-title-md text-primary">Population evidence kept separate</span>
                  <span className="font-body-sm text-body-sm text-on-surface-variant">Population frequency is shown as evidence and, with weight 0, does not change the ranking.</span>
                </div>
              </div>
            </div>
          </div>

          {/* Right Side: Frequency Matrix Comparison Graphic */}
          <div className="lg:col-span-6">
            <div className="bg-surface-container-lowest p-space-xl rounded-2xl shadow-[0_4px_24px_rgba(9,30,58,0.04)]">
              <span className="font-label-sm text-label-sm text-on-surface-variant uppercase tracking-wider font-semibold block mb-space-md">
                Global vs South Asian allele frequency (real ClinVar × gnomAD examples)
              </span>
              <div className="flex flex-col gap-space-sm">
                {failed && <p className="font-body-sm text-body-sm text-on-surface-variant">Population examples could not be loaded.</p>}
                {!data && !failed && <p className="font-body-sm text-body-sm text-on-surface-variant">Loading population examples…</p>}
                {data && data.rows.map((r) => (
                  <div key={r.gene} className="p-space-md rounded-xl bg-surface-container-low flex flex-col gap-space-xs">
                    <div className="flex flex-wrap items-baseline justify-between gap-space-xs">
                      <span className="font-title-md text-title-md text-primary">{r.gene}{r.variant_id ? ` · ${r.variant_id}` : ''}</span>
                      {r.status === 'available' && (
                        <span className="font-body-sm text-body-sm text-on-surface-variant">ClinVar {r.clinical_significance} · {'★'.repeat(r.gold_stars || 0)}</span>
                      )}
                    </div>
                    {r.status !== 'available' ? (
                      <span className="font-body-sm text-body-sm text-on-surface-variant">{r.status}: {r.reason}</span>
                    ) : (
                      <div className="grid grid-cols-3 gap-space-xs">
                        <div>
                          <span className="block font-code-metric text-label-sm text-on-surface-variant">gnomAD Global</span>
                          <span className="font-code-metric text-body-md text-primary">{fmtAf(r.gnomad_global.af)}</span>
                        </div>
                        <div className="bg-secondary-fixed/40 px-space-xs py-space-2xs rounded">
                          <span className="block font-code-metric text-label-sm text-on-secondary-fixed-variant font-bold">gnomAD South Asian</span>
                          <span className="font-code-metric text-body-md text-secondary font-bold">{fmtAf(r.gnomad_south_asian.af)}</span>
                        </div>
                        <div className="bg-surface-container px-space-xs py-space-2xs rounded">
                          <span className="block font-code-metric text-label-sm text-on-surface-variant font-bold">IndiGen</span>
                          <span className="font-code-metric text-body-sm text-on-surface-variant">{r.indigen.status === 'available' ? fmtAf(r.indigen.af) : 'unavailable'}</span>
                        </div>
                      </div>
                    )}
                  </div>
                ))}
              </div>

              <div className="mt-space-md pt-space-sm border-t-0 flex flex-col gap-1 text-on-surface-variant font-label-sm text-label-sm">
                <span>Source: ClinVar P/LP variants × gnomAD v4.1 exomes (allele frequency = AC/AN). Reference examples, not patient data.</span>
                <span>gnomAD South Asian is not India-specific. IndiGen: {data ? data.sources.indigen : '…'}.</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
